def main():
    files = sorted(glob.glob(f'{SITE}/es/*.html')) + sorted(glob.glob(f'{SITE}/es/projects/*.html'))
    total = 0
    for p in files:
        s = open(p, encoding='utf-8').read()
        for a, b in T:
            if a in s:
                total += s.count(a)
                s = s.replace(a, b)
        open(p, 'w', encoding='utf-8').write(s)
    print(f'{total} replacements across {len(files)} files')


main()
